"""Native-role primary tests, exact causal controls and hidden-state comparator."""
import sys,json
from pathlib import Path
import numpy as np
from scipy.stats import binomtest
sys.path.insert(0,str(Path(__file__).parent))
import native_mlp_function_materials_v4 as P
from native_mlp_function_run_v4 import status
from shared.dist_protocol.mechanism_trace import TraceStore,unbits,file_sha

def score(diff,sign,keys):
    d=np.asarray(diff);truth=d*sign;nonzero=d!=0;acc=float(np.mean(truth>0)+.5*np.mean(~nonzero));wins=int(np.sum(truth>0));n=int(nonzero.sum())
    # The nuisance uses discovery-fitted current selector identity only.
    return {'n':len(d),'accuracy':acc,'nonzero_fraction':float(nonzero.mean()),'p':float(binomtest(wins,n,.5,alternative='greater').pvalue) if n else 1.,'mean_oriented_delta':float(truth.mean())}
def main():
    c=P.read(P.OUT/'corpus.json');obs=P.read(P.OUT/'observations.json');pr=P.read(P.PUBLIC/'prereg.research.json');fr=P.read(P.OUT/'execution-freeze.json');assert all(file_sha(P.ROOT/n)==h for n,h in fr['dependencies'].items())
    store=TraceStore();units=c['observed_units'];rows=obs['rows'];items={r['id']:r for r in c['items']};z=np.zeros((len(rows),4,len(units),3),np.float32);hidden=np.zeros((len(rows),4,37,2560),np.float32);early_errors=[];rms={l:np.zeros(9728) for l,u in units};ntrain=0
    for i,r in enumerate(rows):
        d,_=store.manifest(r['trace_id']);a=np.load(store.native_path(r['trace_id'],'hidden_readouts.npy'));hidden[i]=unbits(a).transpose(1,0,2)
        for l in sorted({l for l,u in units}):
            block=store.block(r['trace_id'],l)
            for j,(ul,u) in enumerate(units):
                if ul==l:z[i,:,j]=np.stack([unbits(block[k][:,u]) for k in ['gate','value','activation']],axis=-1)
            if r['split']=='discovery':rms[l]+=unbits(block['activation'][-1])**2
        if r['split']=='discovery':ntrain+=1
        if (i+1)%128==0:status('discovery','running',done=i+1,total=len(rows))
    pairs={};idx={r['id']:i for i,r in enumerate(rows)}
    for split in ['discovery','confirm','lockbox']:
        for family in P.FAMILIES:
            positives=[r for r in rows if r['split']==split and r['family']==family and r['semantic']==1]
            pairs[(split,family)]=[(idx[r['id']],idx[r['id'].rsplit(':',1)[0]+':0']) for r in positives]
    # Freeze signs and strictly matched randoms before accessing heldout differences.
    signs={};rng=np.random.default_rng(P.SEED);random=[];matches=[]
    from server.mechanism_trace_service import parameter
    for family in P.FAMILIES:
        ul=P.FAMILIES[family]['unit'];j=units.index(ul);pp=pairs[('discovery',family)];diff=np.stack([z[a,2,j]-z[b,2,j] for a,b in pp]);signs[family]=np.where(diff.mean(0)>=0,1,-1).tolist()
    for l,u in units:
        a=np.sqrt(rms[l]/ntrain);w=parameter(P.MODEL,f'model.layers.{l}.mlp.down_proj.weight',(slice(None),slice(None)));norm=np.linalg.norm(w,axis=0);ratio=a*norm
        cand=[v for v in range(9728) if v!=u and .8<=a[v]/max(a[u],1e-10)<=1.25 and .8<=norm[v]/max(norm[u],1e-10)<=1.25 and .8<=ratio[v]/max(ratio[u],1e-10)<=1.25];assert cand,(l,u)
        ru=int(rng.choice(cand));random.append([l,ru]);matches.append({'layer':l,'target':u,'random':ru,'A_RMS_ratio':float(a[ru]/a[u]),'down_norm_ratio':float(norm[ru]/norm[u]),'product_ratio':float(ratio[ru]/ratio[u])})
    P.save(P.OUT/'selection.json',{'kind':'real','run_id':P.RUN,'units':units,'random_units':random,'matching':matches,'signs':signs,'fit_split':'discovery only','provenance':obs['provenance']})
    cells=[]
    for split in ['confirm','lockbox']:
        for family in P.FAMILIES:
            rr=[r for r in rows if r['split']==split and r['family']==family]
            for cue in [0,1]:
                for frame in [0,1]:
                    for semantic in [0,1]:
                        sub=[r for r in rr if (r['cue_form'],r['frame'],r['semantic'])==(cue,frame,semantic)];cells.append({'split':split,'family':family,'cue_form':cue,'frame':frame,'semantic':semantic,'n':len(sub),'accuracy':float(np.mean([r['correct'] for r in sub]))})
    findings=[];errors=[];profiles={}
    for family in P.FAMILIES:
        j=units.index(P.FAMILIES[family]['unit']);results={};gate=all(r['accuracy']>=.9 and r['n']>=32 for r in cells if r['family']==family)
        train=pairs[('discovery',family)];direction=np.mean([hidden[a,2,35]-hidden[b,2,35] for a,b in train],axis=0)
        for split in ['confirm','lockbox']:
            pp=pairs[(split,family)];s={}
            for k,name in enumerate(['G','V','A']):
                diff=[z[a,2,j,k]-z[b,2,j,k] for a,b in pp];m=score(diff,signs[family][k],None);m['passed']=bool(m['accuracy']>=.65 and m['p']<.05/4 and m['nonzero_fraction']>=.8);s[name]=m
            s['hidden_pair_direction']={'accuracy':float(np.mean([(hidden[a,2,35]-hidden[b,2,35])@direction>0 for a,b in pp])),'scope':'exploratory supervised response-direction comparator, not SAE or autonomous output prediction'}
            s['early_prefix_max_abs']=float(max(np.max(np.abs(hidden[a,0]-hidden[b,0])) for a,b in pp));s['final_embedding_max_abs']=float(max(np.max(np.abs(hidden[a,2,0]-hidden[b,2,0])) for a,b in pp))
            for a,b in pp:
                diff=z[a,2,j,2]-z[b,2,j,2]
                if diff*signs[family][2]<=0:errors.append({'family':family,'split':split,'positive_id':rows[a]['id'],'negative_id':rows[b]['id'],'positive_trace':rows[a]['trace_id'],'negative_trace':rows[b]['trace_id'],'A_delta':float(diff),'reason':'native_A_order_not_predicted'})
            results[split]=s
        findings.append({'family':family,'title':P.FAMILIES[family]['title'],'unit':P.FAMILIES[family]['unit'],'behavior_gate':gate,'results':results,
            'supported':bool(gate and results['confirm']['A']['passed'] and results['lockbox']['A']['passed'])})
    np.savez(P.OUT/'selected-fields.npz',GVA=z,hidden=hidden)
    result={'kind':'real','run_id':P.RUN,'model_snapshot':c['model_snapshot'],'findings':findings,'cells':cells,'counterexamples':errors,'signs':signs,
        'n_inputs':len(rows),'supported_families':sum(r['supported'] for r in findings),'negative_control_early_pass':all(r['results'][s]['early_prefix_max_abs']==0 and r['results'][s]['final_embedding_max_abs']==0 for r in findings for s in ['confirm','lockbox']),
        'provenance':obs['provenance']}
    P.save(P.OUT/'analysis.json',result);status('prediction','done' if result['supported_families'] else 'not_supported',findings=findings)
    print(json.dumps({'supported_families':result['supported_families'],'negative_controls':result['negative_control_early_pass']}))
if __name__=='__main__':main()

"""Discovery-only long-visible-prefix poles; never read heldout activations."""
from pathlib import Path
import sys,json
import numpy as np
sys.path.insert(0,str(Path(__file__).parent))
import native_mlp_long_materials as OLD
from shared.dist_protocol.mechanism_trace import unbits,file_sha
ROOT=OLD.ROOT;OUT=ROOT/'tests/glm5/result/native_mlp_function_v1';PUBLIC=ROOT/'research/native_mlp_function/v1'
RUN='NMLP-FUNCTION-20261104-v1';MODEL=OLD.MODEL;SEED=4112026
read=OLD.read;save=OLD.save
def main():
    sys.stdout.reconfigure(encoding='utf-8')
    from transformers import AutoTokenizer
    OUT.mkdir(parents=True,exist_ok=True);a=read(OLD.OUT/'analysis.json');data=read(OLD.OUT/'documents.json');tok=AutoTokenizer.from_pretrained(MODEL,local_files_only=True)
    raw=np.load(OLD.OUT/'input-tokens.npy',mmap_mode='r');selected=[]
    for lo,hi in [(6,13),(14,21),(22,29),(30,35)]:
        pool=sorted([c for c in a['cards'] if c['selection']=='stratified_random' and lo<=c['layer']<=hi],key=lambda c:-c['poles']['0:Gpos']['coherence'])
        selected.append(pool[0]);selected.append(next(c for c in pool[1:] if c['layer']!=pool[0]['layer']))
    records=[]
    for c in selected:
        l,u=c['layer'],c['unit'];j=[r['unit'] for r in data['units'] if r['layer']==l].index(u);examples={}
        arrays={k:np.load(OLD.OUT/f'L{l:02d}-{k}.npy',mmap_mode='r') for k in ['G','V','A']}
        for key in ['G','A']:
            x=unbits(np.asarray(arrays[key][:1024,512:,j]))
            for sign in [1,-1]:
                positions=(x*sign).argmax(1)+512;vals=x[np.arange(1024),positions-512];order=np.argsort(-vals*sign)[:12];ee=[]
                for di in order:
                    p=int(positions[di]);ee.append({'doc_index':int(di),'position':p,'visible_tokens':p+1,'current_token_id':int(raw[di,p]),'current_token':tok.decode([int(raw[di,p])]),
                        'prefix':tok.decode(raw[di,:p+1]),'GVA':{k:float(unbits(v[di,p,j])) for k,v in arrays.items()},'doc':data['docs'][di]})
                examples[key+('pos' if sign==1 else 'neg')]=ee
        records.append({'layer':l,'unit':u,'selection':'top discovery-only Gpos h coherence, two distinct layers per prespecified layer group; purposive not random population sample',
            'old_discovery_G_coherence':c['poles']['0:Gpos']['coherence'],'examples':examples})
    result={'kind':'real','run_id':RUN,'model_snapshot':a['model_snapshot'],'units':records,'source_sha256':file_sha(OLD.OUT/'analysis.json'),
        'only_discovery_used':True,'minimum_visible_tokens':513,'provenance':a['provenance']}
    save(OUT/'discovery.json',result)
    for r in records:
        print(f'B{r["layer"]}/U{r["unit"]}',flush=True)
        for pole,ee in r['examples'].items():
            for e in ee[:3]:print(json.dumps({'pole':pole,'token':e['current_token'],'GVA':e['GVA'],'tail':e['prefix'][-250:]},ensure_ascii=False),flush=True)
if __name__=='__main__':main()

"""Descriptive factorial G/V/A audit; never refits the frozen candidate signs."""
import sys,json
from pathlib import Path
import numpy as np
sys.path.insert(0,str(Path(__file__).parent))
import native_mlp_function_materials_v4 as P
from shared.dist_protocol.mechanism_trace import unbits,digest
def main():
    outputs=[]
    for folder in [P.OUT,P.OUT/'place-polarity']:
        c=P.read(folder/('polarity-corpus.json' if folder==P.OUT else 'execution-corpus.json'));result=P.read(folder/'polarity-result.json');selection=P.read(P.OUT/'coordinate-selection.json')['selected']
        if folder!=P.OUT:selection=selection+[{'family':'location','layer':24,'unit':8443,'sign':P.read(P.OUT/'selection.json')['signs']['location'][2]}]
        byid={r['id']:r for r in c['items']};values=np.zeros((128,2,2,2,len(selection),3),np.float32)
        for row in result['rows']:
            item=byid[row['id']];k=int(item['id'].split(':')[1]);root=folder/'polarity-native'/digest(item['id'])[:20]
            for j,u in enumerate(selection):
                with np.load(root/f'block_{u["layer"]:02d}.npz') as z:values[k,item['fact'],item['question_polarity'],:,j]=np.stack([unbits(z[key][:,u['unit']]) for key in ['gate','value','activation']],axis=-1)
        for j,u in enumerate(selection):
            for stage in [0,1]:
                x=values[:,:,:,stage,j];coeff={}
                for name,signs in [('fact',np.array([[-1,-1],[1,1]])),('question',np.array([[-1,1],[-1,1]])),('fact_x_question',np.array([[1,-1],[-1,1]]))]:
                    b=(x*signs[None,:,:,None]).mean((1,2));coeff[name]={'GVA_mean':b.mean(0).tolist(),'GVA_RMS':np.sqrt((b*b).mean(0)).tolist()}
                outputs.append({'diagnostic':'universal' if folder==P.OUT else 'location_name_balanced','layer':u['layer'],'unit':u['unit'],'stage':stage,'coefficients':coeff,
                    'formula':'A(s,q)=a+b_s*s+b_q*q+b_sq*s*q, s/q in{-1,+1}; empirical4-cell contrast, standard factorial decomposition, not a new law or causal proof'})
        np.save(folder/'factorial-GVA.npy',values)
    P.save(P.OUT/'factorial-results.json',{'kind':'real','run_id':P.RUN,'rows':outputs,'provenance':P.read(P.OUT/'observations.json')['provenance'],'status':'posthoc descriptive decomposition, primary verdicts unchanged'})
    print(json.dumps({'unit_stage_comparisons':len(outputs)}))
if __name__=='__main__':main()

"""Trace every changed capability item and representative applied joint edits."""
import sys,time,json
from pathlib import Path
import numpy as np
sys.path.insert(0,str(Path(__file__).parent))
import native_mlp_function_materials_v4 as P
from native_mlp_function_run_v4 import Recorder as BaseRecorder,status
from native_mlp_long_validate import install
from shared.dist_protocol.mechanism_trace import GpuLease,TraceStore,digest,save_json,file_sha
from shared.dist_protocol.natural_register_runner import snapshot

class Recorder(BaseRecorder):
    def __init__(self,*args,annotation=None,**kwargs):super().__init__(*args,**kwargs);self.annotation=annotation or {}
    def finish(self,*args,**kwargs):
        d,p=super().finish(*args,**kwargs);d.update(self.annotation)
        d['causal_visibility']='Readouts refer to the actual padded orunpadded tensor positions; attentionmask is saved when padding was used. No generated answer is part of input.'
        d.pop('trace_id');d['trace_id']=digest(d);save_json(p,d);return d,p
def main():
    import torch
    from transformers import AutoTokenizer,AutoModelForCausalLM
    prov=P.read(P.OUT/'observations.json')['provenance'];groups=P.read(P.OUT/'dose-groups.json')['groups'];store=TraceStore();torch.set_num_threads(4);out=[]
    with GpuLease():
        for _ in range(30):
            if torch.cuda.mem_get_info()[0]>12*2**30:break
            time.sleep(2)
        assert torch.cuda.mem_get_info()[0]>12*2**30 and snapshot(P.MODEL)==prov['model_revision']
        tok=AutoTokenizer.from_pretrained(P.MODEL,local_files_only=True);tok.padding_side='left';m=AutoModelForCausalLM.from_pretrained(P.MODEL,local_files_only=True,dtype=torch.bfloat16,device_map='cuda',attn_implementation='sdpa').eval().requires_grad_(False)
        qs=P.read(P.ROOT/'tests/glm5/result/phase2773_w6_v2/capability-inputs.json');qidx={q['id']:i for i,q in enumerate(qs)};base={r['id']:r for r in P.read(P.OUT/'capability-base.json')};letter=[tok.encode(t,add_special_tokens=False)[0] for t in 'ABCDE']
        for group in ['native','coordinate']:
            edited=P.read(P.OUT/f'capability-{group}.json');changed=[r for r in edited if r['correct']!=base[r['id']]['correct']]
            for row in changed:
                index=qidx[row['id']];chunk=qs[(index//4)*4:(index//4+1)*4];target=next(q for q in chunk if q['id']==row['id']);chunk=[target]+[q for q in chunk if q['id']!=row['id']];tokens=[]
                for q in chunk:
                    text=q['question']+'\n'+'\n'.join(f'{l}. {a}' for l,a in zip('ABCDE',q['choices']))+'\n请只回答正确选项字母。'
                    tokens.append(tok.encode(tok.apply_chat_template([{'role':'user','content':text}],tokenize=False,add_generation_prompt=True,enable_thinking=False),add_special_tokens=False))
                batch={k:v.cuda() for k,v in tok.pad({'input_ids':tokens},padding=True,return_tensors='pt').items()};ids=batch['input_ids'][0].tolist();p=len(ids)-1
                for condition,units in [('base',[]),('edited',groups[group]['units'])]:
                    item={'id':f'cap:{group}:{row["id"]}:{condition}','entity':row['id'],'scope':f'能力题复采 · {group} · {condition}','split':'capability_audit','token_ids':ids,'text':tok.decode(ids),'prompt':tok.decode(ids)}
                    annotation={'intervention':{'kind':'current-query native-unit ablation','units':units,'alpha':1.,'activation_is_intervened':bool(units)},'input_attention_mask':batch['attention_mask'][0].tolist(),
                        'readout_annotations':[{'position':p,'role':'assistant_boundary'}],'capability_audit':{'question_id':row['id'],'group':group,'condition':condition,'gate_eligible':row['gate_eligible'],'original_batch_shape_retained':True}}
                    hs=install(m,units,1.)
                    try:
                        with Recorder(m,[p],P.OUT/'operation-native'/digest(item['id'])[:20],annotation=annotation) as rec:
                            with torch.inference_mode():o=m(**batch,use_cache=False,output_hidden_states=True,logits_to_keep=1)
                    finally:
                        for h in hs:h.remove()
                    d,path=rec.finish(o,item,tok,prov['model_revision'],P.RUN+':capability-audit',prov);store.register(path);pred='ABCDE'[int(o.logits[0,-1,letter[:len(target['choices'])]].argmax())];expected=base[row['id']]['prediction'] if condition=='base' else row['prediction']
                    out.append({'run_id':d['run_id'],'sample_id':item['id'],'trace_id':d['trace_id'],'condition':condition,'group':group,'question_id':row['id'],'replay_prediction':pred,'original_prediction':expected,'prediction_consistent':pred==expected,'input_tokens':len(ids)})
        c=P.read(P.OUT/'corpus.json')
        for item in [r for r in c['items'] if r['family']=='location' and r['family_index']==288]:
            for condition,units in [('base',[]),('native',groups['native']['units']),('coordinate',groups['coordinate']['units'])]:
                copy={**item,'id':f'operation:{item["id"]}:{condition}'};hs=install(m,units,1.)
                try:
                    with Recorder(m,item['readout_positions'],P.OUT/'operation-native'/digest(copy['id'])[:20],annotation={'intervention':{'kind':'current-query native-unit ablation','units':units,'alpha':1.,'activation_is_intervened':bool(units)},'response_profile_stage_indices':[0,1,2,3]}) as rec:
                        with torch.inference_mode():o=m(input_ids=torch.tensor([item['token_ids']]*4,device='cuda'),use_cache=False,output_hidden_states=True,logits_to_keep=1)
                finally:
                    for h in hs:h.remove()
                d,path=rec.finish(o,copy,tok,prov['model_revision'],P.RUN+':operation-audit',prov);store.register(path);out.append({'run_id':d['run_id'],'sample_id':copy['id'],'trace_id':d['trace_id'],'condition':condition,'input_tokens':len(item['token_ids'])})
        assert snapshot(P.MODEL)==prov['model_revision']
    result={'kind':'real','run_id':P.RUN,'rows':out,'provenance':prov,'script_sha256':file_sha(__file__),'scope':'audit replays, not new independent benchmark questions; post-ablation A may differ fromSiLU(G)V bydesign'}
    P.save(P.OUT/'operation-traces.json',result);status('operation_audit',traces=len(out),capability_replay_consistent=all(r.get('prediction_consistent',True) for r in out));print(json.dumps({'traces':len(out)}))
if __name__=='__main__':
    while not (P.OUT/'place-polarity/polarity-result.json').exists():time.sleep(5)
    main()

"""Prospective geographic-place vs portable-object answer/fact control."""
import sys,json,time,types
from pathlib import Path
import numpy as np
from scipy.stats import binomtest
sys.path.insert(0,str(Path(__file__).parent))
import native_mlp_function_materials_v4 as P
import native_mlp_function_polarity as B
import native_mlp_long_materials as OLD
from native_mlp_function_run_v4 import status
from shared.dist_protocol.mechanism_trace import digest,file_sha,save_json
